pub fn lex_src(source: String) -> Vec<Token> {
    let source_revl_cs: std::vec::Vec<char> = source.chars().collect();
    let mut out: Vec<Token> = vec![];
    let mut i = 0i64;
    let mut line = 1i64;
    let n = source.revl_length();
    while (i < n) {
        let s = step(&source, i, line, &source_revl_cs);
        if (s.tok.kind != "") {
            out.push(s.tok.clone());
        }
        i = s.i;
        line = s.line;
    }
    let ll = line;
    out.push(Token { kind: String::from("eof"), text: String::from(""), line: ll });
    return out;
}

fn eof_tok() -> Token {
    return Token { kind: String::from("eof"), text: String::from(""), line: 0i64 };
}

fn tk(ts: Vec<Token>, i: i64) -> Token {
    if (i < ts.revl_length()) {
        return (ts)[(i) as usize].clone();
    }
    return eof_tok();
}

fn at(ts: Vec<Token>, i: i64, k: &str) -> bool {
    return (tk(ts.clone(), i).kind == k);
}

fn at_kw(ts: Vec<Token>, i: i64, w: &str) -> bool {
    let t = tk(ts.clone(), i);
    return ((t.kind == "kw") && (t.text == w));
}

pub fn is_bad(e: Expr) -> bool {
    return match e {
    Expr::Bad(m) => true,
    _ => false,
};
}

fn bad(msg: String) -> PR {
    return PR { i: (0i64).checked_sub(1i64).expect("revl: Int overflow"), e: Expr::Bad(msg.clone()) };
}

pub fn nesting_limit() -> i64 {
    return 200i64;
}

fn too_deep() -> PR {
    return bad(format!("expression nesting is deeper than the parser's limit of {} levels", (nesting_limit()).to_string()));
}

fn join_exprs(xs: Vec<Expr>) -> String {
    let mut out: Vec<String> = vec![];
    let mut i = 0i64;
    while (i < xs.revl_length()) {
        out.push(render((xs)[(i) as usize].clone()));
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return out.revl_join(" ");
}

fn render_arms(xs: Vec<ArmN>) -> String {
    let mut out = vec![];
    let mut i = 0i64;
    while (i < xs.revl_length()) {
        let a = (xs)[(i) as usize].clone();
        let b = if (a.bind == "") { String::from("_") } else { a.bind };
        out.push((((((String::from("(arm ").revl_concat(&a.pat)).revl_concat(" ")).revl_concat(&b)).revl_concat(" ")).revl_concat(&render(a.body.clone()))).revl_concat(")"));
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return out.revl_join(" ");
}

